import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const [first, second] = input;
const [n, k] = first.split(" ").map(Number);
const a = second.split(" ").map(Number);

// mask の i ビット目が 1 なら i 番目を選ぶ。2^N 通りをすべて試す
let count = 0;
for (let mask = 0; mask < 1 << n; mask++) {
  let sum = 0;
  for (let i = 0; i < n; i++) {
    if (mask & (1 << i)) sum += a[i];
  }
  if (sum === k) count++;
}
console.log(count);
